<?php
require __DIR__.'/includes/bootstrap.php'; require_admin(); require __DIR__.'/includes/layout.php';
$counts=['patients'=>(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn(),'appointments'=>(int)$pdo->query('SELECT COUNT(*) FROM appointments')->fetchColumn()];
foreach(['Pending','Approved','Completed','Cancelled'] as $s){$q=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE status=?');$q->execute([$s]);$counts[strtolower($s)]=(int)$q->fetchColumn();}
$recent=$pdo->query("SELECT a.*,CONCAT(p.first_name,' ',p.last_name) patient,CONCAT(d.first_name,' ',d.last_name) dentist FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN dentists d ON d.id=a.dentist_id ORDER BY a.created_at DESC LIMIT 7")->fetchAll();
$upcoming=$pdo->query("SELECT a.*,CONCAT(p.first_name,' ',p.last_name) patient,CONCAT(d.first_name,' ',d.last_name) dentist FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN dentists d ON d.id=a.dentist_id WHERE a.status='Approved' AND TIMESTAMP(a.appointment_date,a.start_time)>=NOW() ORDER BY a.appointment_date,a.start_time LIMIT 6")->fetchAll();
$services=$pdo->query("SELECT service_name_snapshot name,COUNT(*) total FROM appointments GROUP BY service_name_snapshot ORDER BY total DESC LIMIT 5")->fetchAll();
$total=max(1,$counts['appointments']);$p1=round($counts['pending']/$total*100);$p2=$p1+round($counts['approved']/$total*100);$p3=$p2+round($counts['completed']/$total*100);
page_header('Dashboard','dashboard');
?><section class="grid stats"><?php foreach(['patients'=>'Registered Patients','appointments'=>'Total Appointments','pending'=>'Pending','approved'=>'Approved','completed'=>'Completed','cancelled'=>'Cancelled'] as $k=>$label):?><div class="stat"><strong><?=number_format($counts[$k])?></strong><span><?=e($label)?></span></div><?php endforeach?></section><section class="grid panels"><div class="card"><div class="toolbar"><h2>Recent appointment requests</h2><a class="btn secondary sm" href="appointments.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Dentist</th><th>Schedule</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $a):?><tr><td><?=e($a['patient'])?></td><td>Dr. <?=e($a['dentist'])?></td><td><?=date('M j, Y',strtotime($a['appointment_date']))?> · <?=date('g:i A',strtotime($a['start_time']))?></td><td><?=status_badge($a['status'])?></td></tr><?php endforeach?><?php if(!$recent):?><tr><td colspan="4" class="empty">No appointment requests yet.</td></tr><?php endif?></tbody></table></div></div><div class="card"><h2>Appointment status distribution</h2><div class="donut" style="--pending:<?=$p1?>%;--approved:<?=$p2?>%;--completed:<?=$p3?>%"></div><div class="legend"><span>Pending <?=$counts['pending']?></span><span>Approved <?=$counts['approved']?></span><span>Completed <?=$counts['completed']?></span><span>Cancelled <?=$counts['cancelled']?></span></div></div><div class="card"><h2>Upcoming appointments</h2><div class="table-wrap"><table><tbody><?php foreach($upcoming as $a):?><tr><td><strong><?=e($a['patient'])?></strong><br><small><?=date('M j · g:i A',strtotime($a['appointment_date'].' '.$a['start_time']))?></small></td><td>Dr. <?=e($a['dentist'])?></td></tr><?php endforeach?><?php if(!$upcoming):?><tr><td class="empty">No upcoming appointments.</td></tr><?php endif?></tbody></table></div></div><div class="card"><h2>Most-booked services</h2><div class="table-wrap"><table><thead><tr><th>Service</th><th>Bookings</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?=e($s['name'])?></td><td><strong><?=$s['total']?></strong></td></tr><?php endforeach?><?php if(!$services):?><tr><td colspan="2" class="empty">No booking data yet.</td></tr><?php endif?></tbody></table></div></div></section><?php page_footer();
